import sqlite3


def insert_export(conn, tenant_id, request_id, payload):
    """Insert one export on a sqlite3.Connection; a locked database raises TimeoutError."""
    try:
        cursor = conn.execute(
            "INSERT INTO exports (tenant_id, request_id, payload) VALUES (?, ?, ?) "
            "ON CONFLICT (tenant_id, request_id) DO NOTHING RETURNING *",
            (tenant_id, request_id, payload),
        )
    except sqlite3.OperationalError as exc:
        if "locked" in str(exc):
            raise TimeoutError(str(exc)) from exc
        raise
    return cursor.fetchone()
